{
  "requirement_id": "REQ-005",
  "cases": [
    {
      "id": "TC-1",
      "title": "Valid transitions: todo to in_progress, in_progress to done, in_progress to todo",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} when task is in todo status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} when task is in in_progress status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} when task is in in_progress status"
      ],
      "expected": "允許從 todo 流轉至 in_progress；允許從 in_progress 流轉至 done；允許從 in_progress 流轉至 todo"
    },
    {
      "id": "TC-2",
      "title": "Forbidden transitions from done state",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} when task is in done status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} when task is in done status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} when task is in done status"
      ],
      "expected": "done 為終態，任何從 done出發的流轉均應回傳 409 且任務狀態保持不變"
    },
    {
      "id": "TC-3",
      "title": "Other unlisted transitions and self-transitions",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"done\"} when task is in todo status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"todo\"} when task is in todo status",
        "POST /api/tasks/{tid}/transition with {\"to\": \"in_progress\"} when task is in in_progress status"
      ],
      "expected": "其他未列出的流轉（包含 todo 至 done、以及相同狀態的轉換）均應回傳 409"
    },
    {
      "id": "TC-4",
      "title": "Invalid status parameter in transition request",
      "surface": "api",
      "steps": [
        "POST /api/tasks/{tid}/transition with {\"to\": \"invalid_status\"}"
      ],
      "expected": "當請求中的 to 參數不是合法狀態時，應回傳 422"
    }
  ]
}

